export const COURSE_MODULES = [
  [ // 1 Full Stack Web Development
    { id:"m1", title:"Introduction to Full Stack Development", icon:"💡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:00", watchSeconds:6, caption:"Visual overview — Introduction to Full Stack Development", content:"Full stack development means being comfortable working on both the front end (what a user sees and interacts with in the browser) and the back end (the server, database and application logic that power it). A full stack developer understands how a request travels from a click in the browser, through the network, into a server, out to a database, and back again as a rendered page or JSON response.\n\nIn this course we split that journey into layers: HTML/CSS/JavaScript on the client, a Node.js/Express server in the middle, and a database at the back. Learning to reason about each layer separately — and then how they talk to each other — is the single most useful skill for building real products.\n\nBy the end of this module you should be able to describe, in your own words, what happens between typing a URL and seeing a page appear." },
    { id:"m2", title:"Front-End Foundations", icon:"🔍", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"4:53", watchSeconds:7, caption:"Visual overview — Front-End Foundations", content:"The front end is built from three technologies working together: HTML for structure, CSS for presentation, and JavaScript for behaviour. HTML organises content into a tree of elements; CSS selects those elements and applies visual rules like colour, spacing and layout; JavaScript listens for events (clicks, typing, page loads) and updates the page dynamically.\n\nModern front-end work usually happens through a framework such as React, which lets you describe your UI as small reusable components and lets the framework handle efficiently updating the DOM when data changes. Understanding plain HTML/CSS/JS first makes frameworks much easier to learn, because a framework is really just a structured way of doing the same three things at scale.\n\nKey habits to build here: always think in components, keep state (the data driving your UI) separate from presentation, and test your UI at different screen sizes early rather than at the end." },
    { id:"m3", title:"Back-End & APIs", icon:"🧩", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:46", watchSeconds:8, caption:"Visual overview — Back-End & APIs", content:"The back end exposes an API — a set of URLs that the front end can call to read or change data. A typical API endpoint accepts a request (often JSON), performs some logic or database lookup, and returns a response with a status code such as 200 (success), 404 (not found) or 500 (server error).\n\nNode.js with the Express framework is a common way to build these APIs in JavaScript, which has the advantage of letting you use one language across the whole stack. Middleware functions handle cross-cutting concerns like authentication, logging and input validation before a request reaches its final handler.\n\nSecurity matters from day one: never trust data coming from the client, always validate and sanitise input, and keep secrets such as database passwords out of your source code using environment variables." },
    { id:"m4", title:"Databases & Deployment", icon:"🛠️", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:39", watchSeconds:9, caption:"Visual overview — Databases & Deployment", content:"Data needs to persist somewhere between requests, which is the job of a database. Relational databases (like PostgreSQL or MySQL) store data in tables with defined relationships and are a strong default choice for most applications; NoSQL databases (like MongoDB) store flexible JSON-like documents and suit rapidly changing or loosely structured data.\n\nOnce your app works locally, deployment is the process of making it reachable on the internet: building your front end into static assets, running your server on a hosting platform, and pointing a domain name at it. Continuous integration pipelines automatically run your tests and deploy new versions whenever you push code, catching mistakes before real users see them.\n\nA finished full stack project ties all of this together: a React front end talking to an Express API, backed by a database, deployed and monitored in production." },
  ],
  [ // 2 Python for Data Science
    { id:"m1", title:"Python Essentials for Data Work", icon:"🚀", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"4:37", watchSeconds:7, caption:"Visual overview — Python Essentials for Data Work", content:"Python is popular in data science because its syntax is readable and it has a mature ecosystem of libraries built specifically for working with data. Before touching those libraries, you need to be comfortable with core Python: variables, lists, dictionaries, loops, functions and how to read error messages.\n\nA data scientist spends a lot of time in an interactive environment such as Jupyter Notebook, where you can run small chunks of code, inspect the output immediately, and iterate quickly rather than writing a full program up front and running it once.\n\nGet comfortable with list and dictionary comprehensions early — they are the idiomatic way to transform data in Python and you will see them constantly in other people's code." },
    { id:"m2", title:"NumPy — Numerical Computing", icon:"📐", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:30", watchSeconds:8, caption:"Visual overview — NumPy — Numerical Computing", content:"NumPy introduces the array, a grid of numbers that supports fast, vectorised operations — meaning you apply a calculation to an entire array at once instead of writing a manual loop. This is both far faster and far more concise than plain Python loops when working with large amounts of numeric data.\n\nArrays can be one-dimensional (like a list of numbers), two-dimensional (like a table), or higher-dimensional. Broadcasting is the rule NumPy uses to apply operations between arrays of different shapes, and understanding it well prevents a lot of confusing bugs later.\n\nMost other data science libraries, including pandas and scikit-learn, are built on top of NumPy arrays, so a solid grasp here pays off throughout the rest of the course." },
    { id:"m3", title:"pandas — Working with Real Data", icon:"🧠", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:23", watchSeconds:9, caption:"Visual overview — pandas — Working with Real Data", content:"pandas provides the DataFrame, a table-like structure with labelled rows and columns, which is the standard way to load, clean and explore real-world datasets in Python. Typical tasks include reading a CSV file, filtering rows based on a condition, handling missing values, grouping data to compute summary statistics, and joining multiple tables together.\n\nData cleaning is often the majority of real work in data science: renaming columns, fixing inconsistent types, removing duplicates and deciding how to treat missing or outlier values. Doing this carelessly quietly corrupts every analysis that follows, so it deserves real attention rather than being rushed.\n\nOnce your data is clean, grouping and aggregation (for example, average sales per region per month) is how you turn raw rows into insight." },
    { id:"m4", title:"Visualisation & First Insights", icon:"🔗", gradFrom:"#F4A400", gradTo:"#78350F", duration:"7:16", watchSeconds:10, caption:"Visual overview — Visualisation & First Insights", content:"A chart often communicates a pattern faster than a table of numbers ever could. Libraries such as Matplotlib and Seaborn let you build line charts, bar charts, histograms and scatter plots directly from pandas DataFrames, which is useful both for your own exploration and for presenting findings to others.\n\nGood visual habits: label your axes, choose a chart type that matches the question you are asking (trends over time suit line charts, comparisons across categories suit bar charts, and relationships between two numeric variables suit scatter plots), and avoid cluttering a chart with more information than the reader needs.\n\nBy the end of this module you should be able to take a raw CSV file and produce a short, clearly visualised summary of what it contains." },
  ],
  [ // 3 UI/UX Design Fundamentals
    { id:"m1", title:"What UX Design Actually Is", icon:"📊", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:14", watchSeconds:8, caption:"Visual overview — What UX Design Actually Is", content:"User experience (UX) design is the practice of shaping how a product feels to use — how easy it is to understand, how quickly someone can complete a task, and how confident they feel while doing it. User interface (UI) design is a subset of this: the visual layer of buttons, colours, typography and spacing that the user actually sees.\n\nGood UX starts with understanding the user's goal before designing any screen. Techniques like user interviews, personas (fictional but realistic representative users) and user journeys help a designer stay grounded in real needs rather than personal preference.\n\nA useful mindset: you are not designing a screen, you are designing a path for someone to get something done." },
    { id:"m2", title:"Design Principles & Visual Hierarchy", icon:"🎯", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:07", watchSeconds:9, caption:"Visual overview — Design Principles & Visual Hierarchy", content:"Visual hierarchy is the deliberate ordering of elements on a screen so the eye naturally lands on the most important thing first. This is achieved through size, colour contrast, spacing and position rather than decoration.\n\nConsistency is another core principle: reusing the same button styles, spacing rules and language throughout a product reduces the mental effort required to use it, because users only have to learn a pattern once. Whitespace (empty space) is not wasted space — it groups related items together and gives busy interfaces room to breathe.\n\nColour and typography choices should support hierarchy and brand, not fight against readability; sufficient contrast between text and background is essential for accessibility." },
    { id:"m3", title:"Wireframing & Prototyping", icon:"🧭", gradFrom:"#F4A400", gradTo:"#78350F", duration:"7:00", watchSeconds:10, caption:"Visual overview — Wireframing & Prototyping", content:"A wireframe is a low-fidelity sketch of a screen's layout, focused on structure and content placement rather than visual polish — it is deliberately rough so that feedback focuses on the right things at the right stage. Moving from wireframes to a clickable prototype lets you (and real test users) experience the flow of a product before a single line of code is written.\n\nTools such as Figma let designers build interactive prototypes by linking together frames, which is invaluable for catching confusing flows early, when they are cheap to fix, rather than after development.\n\nIterating based on user testing — watching real people try to complete a task and noting where they hesitate or get stuck — is far more reliable than assuming you know how users will behave." },
    { id:"m4", title:"Usability Testing & Handoff", icon:"📌", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:53", watchSeconds:11, caption:"Visual overview — Usability Testing & Handoff", content:"Usability testing means observing real (or representative) users attempting real tasks with your design, and recording where they succeed, hesitate or fail. Even testing with five users tends to reveal most of the major usability problems in a design.\n\nOnce a design is validated, handoff to developers requires clear specifications: exact spacing, colours, font sizes and interactive states (default, hover, disabled) so the built product matches the intended design.\n\nDesign is never really \"finished\" — most successful products continue to run small usability tests and refine their interface after launch based on real usage data." },
  ],
  [ // 4 React JS — From Zero to Hero
    { id:"m1", title:"Components & JSX", icon:"🖼️", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"5:51", watchSeconds:9, caption:"Visual overview — Components & JSX", content:"React organises a UI into components — small, self-contained pieces of interface (a button, a card, a whole page) that can be combined like building blocks. JSX is the syntax that lets you write HTML-like markup directly inside JavaScript, which React then converts into actual DOM updates behind the scenes.\n\nA component is just a function that returns what should appear on screen based on its inputs (called props). Because components are just functions, they are easy to test, reuse and reason about in isolation.\n\nThinking in components means breaking a design into the smallest reusable pieces before writing any code — this single habit prevents most of the mess found in poorly structured React apps." },
    { id:"m2", title:"State & Hooks", icon:"🧱", gradFrom:"#F4A400", gradTo:"#78350F", duration:"6:44", watchSeconds:10, caption:"Visual overview — State & Hooks", content:"State is data that changes over time and drives what a component renders — for example, whether a menu is open or the text currently typed into a search box. The useState hook lets a function component hold and update this kind of data, automatically re-rendering the component whenever it changes.\n\nThe useEffect hook lets a component run side effects — code that reaches outside of rendering, such as fetching data from an API or subscribing to an event — at the right moment in a component's lifecycle.\n\nA common beginner mistake is mutating state directly instead of using the provided setter function; React relies on you creating a new value so it knows to re-render." },
    { id:"m3", title:"Handling Data & Forms", icon:"⚙️", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:37", watchSeconds:11, caption:"Visual overview — Handling Data & Forms", content:"Most real applications fetch data from an API and display it, then let users submit forms that send data back. In React this typically means calling fetch or a library like Axios inside a useEffect, storing the result in state, and rendering different UI depending on whether the data is loading, loaded, or failed to load.\n\nForms in React are usually \"controlled,\" meaning the input's value is tied directly to state and updated on every keystroke, giving you full control to validate or transform input as the user types.\n\nHandling loading and error states explicitly, rather than assuming every request succeeds instantly, is what separates a demo from a production-ready interface." },
    { id:"m4", title:"Component Design & State Management", icon:"🔬", gradFrom:"#0891B2", gradTo:"#164E63", duration:"8:30", watchSeconds:6, caption:"Visual overview — Component Design & State Management", content:"As an app grows, deciding where state should live becomes an important design decision. A common rule of thumb is to keep state as close as possible to where it is used, and only lift it up to a shared parent component when multiple components genuinely need access to the same data.\n\nFor larger applications, dedicated state management tools or React's built-in Context API help share data across many components without manually passing props down through every layer (sometimes called \"prop drilling\").\n\nA well-structured React application reads like a tree of small, predictable components, each responsible for one clear job." },
  ],
  [ // 5 SQL & Database Design
    { id:"m1", title:"Relational Database Basics", icon:"📡", gradFrom:"#F4A400", gradTo:"#78350F", duration:"6:28", watchSeconds:10, caption:"Visual overview — Relational Database Basics", content:"A relational database stores data in tables made up of rows and columns, similar to a spreadsheet, but with strict rules connecting related tables together. Each table typically represents one type of entity — students, courses, orders — and each row is one specific record of that entity.\n\nEvery table usually has a primary key, a column (or combination of columns) that uniquely identifies each row. Other tables reference that primary key through a foreign key, which is how relational databases represent relationships, such as a student being enrolled in a course.\n\nThinking in tables and relationships, rather than as one giant spreadsheet, is the core mental shift required to design good databases." },
    { id:"m2", title:"Writing SQL Queries", icon:"🧮", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:21", watchSeconds:11, caption:"Visual overview — Writing SQL Queries", content:"SQL (Structured Query Language) is how you ask a relational database for data. A SELECT statement retrieves rows, WHERE filters which rows are returned, and ORDER BY controls the order of results. These three clauses alone cover a large share of everyday queries.\n\nJOIN clauses combine rows from two or more tables based on a matching column, which is essential once your data is spread across related tables rather than duplicated everywhere. GROUP BY, combined with aggregate functions like COUNT, SUM and AVG, lets you summarise data — for example, the number of students enrolled per course.\n\nWriting SQL well is largely about being precise: a small mistake in a WHERE clause can silently return the wrong rows rather than throwing an obvious error." },
    { id:"m3", title:"Normalization & Schema Design", icon:"🗂️", gradFrom:"#0891B2", gradTo:"#164E63", duration:"8:14", watchSeconds:6, caption:"Visual overview — Normalization & Schema Design", content:"Normalization is the process of organising tables to reduce data duplication and avoid inconsistencies — for example, storing a student's name in one place rather than repeating it in every course they are enrolled in. Following a few standard normal forms helps you design schemas that stay consistent as an application grows.\n\nHowever, normalization is a tool, not a religion: sometimes a small amount of duplication is intentionally accepted to make queries faster, a trade-off known as denormalization, typically used in reporting or analytics systems.\n\nGood schema design also means choosing sensible data types and constraints (such as NOT NULL or UNIQUE) so the database itself helps prevent bad data rather than relying entirely on application code." },
    { id:"m4", title:"Indexes & Performance", icon:"🎬", gradFrom:"#BE185D", gradTo:"#500724", duration:"9:07", watchSeconds:7, caption:"Visual overview — Indexes & Performance", content:"An index is a separate structure the database maintains to make looking up rows by a particular column much faster, at the cost of some extra storage and slightly slower writes. Without an index, the database may need to scan every row in a table to find matches, which becomes very slow as tables grow.\n\nChoosing which columns to index is a balance: index columns that are frequently searched or joined on, but avoid over-indexing tables that are written to very often, since every index adds overhead to inserts and updates.\n\nUnderstanding how your queries are actually executed — using a tool like EXPLAIN — is the most reliable way to diagnose why a query is slow rather than guessing." },
  ],
  [ // 6 AWS Cloud Practitioner
    { id:"m1", title:"What Cloud Computing Solves", icon:"🧬", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:05", watchSeconds:11, caption:"Visual overview — What Cloud Computing Solves", content:"Cloud computing means renting computing resources — servers, storage, databases — from a provider like AWS instead of buying and maintaining your own physical hardware. This turns a large upfront cost into a flexible, pay-as-you-go expense, and lets you scale resources up or down based on real demand.\n\nAWS organises the world into Regions (geographic areas) and Availability Zones (physically separate data centres within a region), which lets you design applications that stay available even if one data centre has a problem.\n\nUnderstanding the shared responsibility model is essential: AWS secures the underlying infrastructure, while you remain responsible for securing what you build and configure on top of it." },
    { id:"m2", title:"Core Compute & Storage Services", icon:"🪄", gradFrom:"#0891B2", gradTo:"#164E63", duration:"7:58", watchSeconds:6, caption:"Visual overview — Core Compute & Storage Services", content:"EC2 (Elastic Compute Cloud) provides virtual servers that you can start, stop and resize on demand, forming the backbone of many applications hosted on AWS. S3 (Simple Storage Service) provides highly durable object storage, commonly used for files, backups, images and static website content.\n\nChoosing the right compute option matters: EC2 gives full control over the server, while serverless options like AWS Lambda let you run code in response to events without managing any server at all, which suits smaller, event-driven workloads.\n\nStorage and compute are billed separately and in different units, so understanding a service's pricing model is part of designing a cost-effective solution." },
    { id:"m3", title:"Databases & Networking on AWS", icon:"📚", gradFrom:"#BE185D", gradTo:"#500724", duration:"8:51", watchSeconds:7, caption:"Visual overview — Databases & Networking on AWS", content:"AWS offers managed database services such as RDS (for relational databases like PostgreSQL and MySQL) and DynamoDB (a managed NoSQL database), which remove the burden of manually patching, backing up and scaling a database server.\n\nVPC (Virtual Private Cloud) lets you define your own isolated network within AWS, controlling exactly which resources can talk to each other and to the public internet, which is fundamental to building a secure architecture.\n\nA typical simple architecture places a web server in a public subnet and a database in a private subnet that only the web server can reach, limiting the database's exposure to the outside world." },
    { id:"m4", title:"Security, Cost & the Well-Architected Mindset", icon:"🧾", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"9:44", watchSeconds:8, caption:"Visual overview — Security, Cost & the Well-Architected Mindset", content:"IAM (Identity and Access Management) controls who — or what service — is allowed to do what within your AWS account, following the principle of least privilege: only grant the exact permissions needed, nothing more.\n\nAWS provides tools like the Billing Dashboard and Cost Explorer to track spending, and following practices such as shutting down unused resources and choosing the right instance size prevents unexpected bills.\n\nThe AWS Well-Architected Framework summarises best practice across six pillars — operational excellence, security, reliability, performance efficiency, cost optimization and sustainability — which is a useful checklist when reviewing any cloud design." },
  ],
  [ // 7 Flutter App Development
    { id:"m1", title:"Introduction to Flutter & Dart", icon:"💡", gradFrom:"#0891B2", gradTo:"#164E63", duration:"7:42", watchSeconds:6, caption:"Visual overview — Introduction to Flutter & Dart", content:"Flutter is Google's framework for building natively compiled apps for mobile, web and desktop from a single codebase, written in the Dart programming language. Instead of relying on native UI components, Flutter draws every pixel itself, which gives it very consistent behaviour across platforms.\n\nDart will feel familiar if you know any object-oriented, curly-brace language; its main learning curve is understanding how it integrates tightly with Flutter's widget system.\n\nEverything visible in a Flutter app — text, buttons, padding, even layout itself — is a widget, and understanding this \"everything is a widget\" philosophy is the key to reading and writing Flutter code fluently." },
    { id:"m2", title:"Widgets & Layout", icon:"🔍", gradFrom:"#BE185D", gradTo:"#500724", duration:"8:35", watchSeconds:7, caption:"Visual overview — Widgets & Layout", content:"Flutter widgets are either stateless (they render the same output for the same input and never change on their own) or stateful (they can rebuild themselves in response to changing data). Layout widgets like Row, Column and Container let you position and size other widgets, similar to how CSS Flexbox works on the web.\n\nComposing many small widgets together — rather than building one giant widget — keeps your UI code readable and makes each piece independently reusable and testable.\n\nHot reload, one of Flutter's standout developer experience features, lets you see the result of a code change almost instantly without restarting the whole app, dramatically speeding up UI iteration." },
    { id:"m3", title:"State Management & Navigation", icon:"🧩", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"9:28", watchSeconds:8, caption:"Visual overview — State Management & Navigation", content:"As an app grows beyond a couple of screens, deciding how state is shared and updated across widgets becomes important. Flutter's built-in setState works well for simple, local state, while dedicated state management approaches (such as Provider or Riverpod) help manage state that many different screens need to read or update.\n\nNavigation in Flutter is handled through a stack of routes: pushing a new route shows a new screen on top, and popping returns to the previous one, similar to how a physical stack of cards works.\n\nDesigning a clear navigation structure early — which screens exist and how a user moves between them — avoids a tangled mess of ad-hoc navigation logic later." },
    { id:"m4", title:"Connecting to APIs & Publishing", icon:"🛠️", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"10:21", watchSeconds:9, caption:"Visual overview — Connecting to APIs & Publishing", content:"Real apps need real data, which usually means calling a backend API using packages like http or Dio, parsing the JSON response, and updating the UI once the data arrives — handled carefully alongside loading and error states.\n\nBefore publishing, an app needs testing on real devices of different sizes, proper app icons and metadata, and platform-specific configuration for both the Google Play Store and Apple App Store.\n\nFlutter's single-codebase promise significantly reduces — though does not entirely eliminate — the extra work of supporting both major mobile platforms." },
  ],
  [ // 8 Machine Learning with Python
    { id:"m1", title:"What Machine Learning Really Is", icon:"🚀", gradFrom:"#BE185D", gradTo:"#500724", duration:"8:19", watchSeconds:7, caption:"Visual overview — What Machine Learning Really Is", content:"Machine learning is the practice of letting a computer find patterns in data rather than writing explicit rules by hand. Instead of programming \"if income is above X and age is below Y, approve the loan,\" you show the model many past examples with their outcomes, and it learns the pattern that best predicts new cases.\n\nThe three broad categories are supervised learning (learning from labelled examples, such as predicting house prices from past sales), unsupervised learning (finding structure in unlabeled data, such as grouping similar customers), and reinforcement learning (learning through trial and error with rewards, used in areas like game-playing agents).\n\nA model is only as good as the data it learns from — poor quality or biased data reliably produces poor quality or biased predictions, regardless of the sophistication of the algorithm used." },
    { id:"m2", title:"The Supervised Learning Workflow", icon:"📐", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"9:12", watchSeconds:8, caption:"Visual overview — The Supervised Learning Workflow", content:"A typical supervised learning project follows a consistent workflow: split your data into a training set and a test set, train a model on the training set, and evaluate it honestly on the test set it has never seen, to estimate how well it will perform on new, real-world data.\n\nRegression problems predict a continuous number (like a price), while classification problems predict a category (like spam or not spam). The choice of algorithm — linear regression, decision trees, or more complex models — depends on the nature of the data and the problem.\n\nOverfitting, where a model memorises the training data instead of learning general patterns, is one of the most common pitfalls; it shows up as excellent training performance paired with poor test performance." },
    { id:"m3", title:"Feature Engineering & Model Evaluation", icon:"🧠", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"10:05", watchSeconds:9, caption:"Visual overview — Feature Engineering & Model Evaluation", content:"Features are the input variables a model learns from, and choosing or transforming them well — called feature engineering — often has a bigger impact on model performance than the choice of algorithm itself. This can include scaling numeric values, encoding categories as numbers, or creating new features that better capture the underlying pattern.\n\nEvaluation metrics differ by problem type: accuracy, precision and recall are common for classification, while mean squared error is common for regression. Choosing the right metric matters — for example, in a rare disease detection model, accuracy alone can be dangerously misleading if the disease is very rare.\n\nCross-validation — repeatedly splitting the data in different ways and averaging results — gives a more reliable estimate of real-world performance than a single train/test split." },
    { id:"m4", title:"From Model to Real Application", icon:"🔗", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"10:58", watchSeconds:10, caption:"Visual overview — From Model to Real Application", content:"Building a model in a notebook is only part of the job; deploying it means wrapping it so other software can request predictions, typically through an API, and monitoring how it performs once it meets real, changing data.\n\nModel performance can silently degrade over time as real-world patterns shift, a phenomenon called data drift — which is why production ML systems need ongoing monitoring, not a one-time evaluation.\n\nResponsible use of machine learning also means actively checking for bias in both the training data and the model's predictions, especially for models that affect real people's opportunities or outcomes." },
  ],
  [ // 9 HTML & CSS for Beginners
    { id:"m1", title:"Structuring Content with HTML", icon:"📊", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"8:56", watchSeconds:8, caption:"Visual overview — Structuring Content with HTML", content:"HTML (HyperText Markup Language) describes the structure and meaning of a web page using elements like headings, paragraphs, links, images and lists. Choosing the right element for the job — a heading for a title, a list for a set of items — is called semantic HTML, and it matters both for accessibility and for how well search engines understand your page.\n\nEvery HTML document has a consistent skeleton: a doctype declaration, an html element containing a head (metadata like the page title) and a body (the visible content).\n\nA well-structured HTML document should make sense even with all styling removed — that is a good test of whether your structure is meaningful rather than purely visual." },
    { id:"m2", title:"Styling with CSS", icon:"🎯", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"9:49", watchSeconds:9, caption:"Visual overview — Styling with CSS", content:"CSS (Cascading Style Sheets) controls how HTML elements look: colour, font, spacing, borders and layout. Selectors target which elements a rule applies to, and the \"cascade\" in the name refers to the rules that decide which style wins when multiple rules could apply to the same element.\n\nThe box model is fundamental to CSS: every element is a rectangular box made up of content, padding, border and margin, and understanding how these interact is essential for controlling spacing precisely.\n\nLearning to use browser developer tools to inspect and tweak CSS live is one of the fastest ways to understand why a layout looks the way it does." },
    { id:"m3", title:"Layout with Flexbox", icon:"🧭", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"10:42", watchSeconds:10, caption:"Visual overview — Layout with Flexbox", content:"Flexbox is a CSS layout method designed for arranging items in a single row or column, automatically handling spacing, alignment and sizing between them. Setting display: flex on a container turns its direct children into flex items that can be aligned, ordered, or resized to fill available space.\n\nCommon flexbox properties include justify-content (alignment along the main axis) and align-items (alignment along the cross axis), which together solve the majority of everyday alignment problems that used to require awkward workarounds.\n\nFlexbox is ideal for components like navigation bars, card rows and centering content — patterns that appear in nearly every website." },
    { id:"m4", title:"Responsive Design Basics", icon:"📌", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"11:35", watchSeconds:11, caption:"Visual overview — Responsive Design Basics", content:"Responsive design means building a page that looks good and works well on any screen size, from a small phone to a large desktop monitor. Media queries let you apply different CSS rules depending on the width of the browser window, commonly used to switch a multi-column layout to a single column on small screens.\n\nA mobile-first approach — designing for small screens first, then progressively adding complexity for larger screens — tends to produce cleaner, more focused designs than starting from a large desktop layout and trying to shrink it down.\n\nTesting your page at multiple screen widths as you build, rather than only at the end, catches layout problems while they are still easy to fix." },
  ],
  [ // 10 Node.js & Express Backend
    { id:"m1", title:"Node.js Fundamentals", icon:"🖼️", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"9:33", watchSeconds:9, caption:"Visual overview — Node.js Fundamentals", content:"Node.js lets you run JavaScript outside the browser, most commonly to build servers. Its defining feature is a non-blocking, event-driven model: instead of waiting idly for a slow operation like a database query to finish, Node continues handling other requests and comes back once the result is ready, which lets a single server handle many simultaneous connections efficiently.\n\nnpm (Node Package Manager) gives access to a vast ecosystem of reusable packages, and a package.json file records exactly which packages and versions your project depends on.\n\nUnderstanding asynchronous JavaScript — callbacks, promises, and the more readable async/await syntax — is essential in Node, since almost everything involving files, networks or databases happens asynchronously." },
    { id:"m2", title:"Building APIs with Express", icon:"🧱", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"10:26", watchSeconds:10, caption:"Visual overview — Building APIs with Express", content:"Express is a minimal, flexible framework that sits on top of Node.js and makes it straightforward to define routes — URL patterns paired with the code that should run when a request matches them. A route handler receives a request object and a response object, reads whatever it needs from the request, and sends back a response.\n\nMiddleware functions run before your route handlers and are used for shared concerns like parsing JSON request bodies, logging incoming requests, or checking whether a user is authenticated.\n\nOrganising routes into separate files by resource (for example, all course-related routes together) keeps a growing API manageable rather than becoming one enormous file." },
    { id:"m3", title:"Working with Databases", icon:"⚙️", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"11:19", watchSeconds:11, caption:"Visual overview — Working with Databases", content:"Most Express APIs connect to a database to persist data beyond a single request. Libraries such as Mongoose (for MongoDB) or an ORM like Sequelize or Prisma (for SQL databases) provide a more convenient, structured way to read and write data than writing raw queries by hand every time.\n\nConnection pooling — reusing a small set of database connections rather than opening a new one for every request — is important for performance once your API handles meaningful traffic.\n\nHandling database errors gracefully, and never trusting client input before it reaches a query, protects both the stability and the security of your application." },
    { id:"m4", title:"Authentication & Deployment", icon:"🔬", gradFrom:"#F4A400", gradTo:"#78350F", duration:"12:12", watchSeconds:6, caption:"Visual overview — Authentication & Deployment", content:"Authentication verifies who a user is, typically through a login endpoint that checks credentials and issues a token (such as a JWT) that the client includes on subsequent requests to prove its identity. Passwords should never be stored as plain text — they must be hashed using an algorithm designed for that purpose, such as bcrypt.\n\nAuthorization is a separate concern from authentication: it decides what an already-identified user is allowed to do, such as restricting course editing to admin accounts only.\n\nDeploying a Node.js API involves choosing a hosting platform, setting environment variables for secrets, and ideally running the app behind a process manager that restarts it automatically if it crashes." },
  ],
  [ // 11 Data Structures & Algorithms
    { id:"m1", title:"Why Data Structures Matter", icon:"📡", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"10:10", watchSeconds:10, caption:"Visual overview — Why Data Structures Matter", content:"A data structure is simply a way of organising data so that certain operations — searching, inserting, deleting — can be done efficiently. Choosing the right structure for a problem can be the difference between code that runs instantly and code that grinds to a halt as data grows.\n\nBig-O notation is the standard way to describe how an algorithm's running time or memory use grows as input size increases, letting you compare approaches without depending on a specific computer's speed. Common complexities, from fastest to slowest growing, include constant, logarithmic, linear, linearithmic and quadratic time.\n\nDeveloping an instinct for which operations are \"cheap\" and which are \"expensive\" for a given structure is one of the most transferable skills in all of programming." },
    { id:"m2", title:"Core Structures: Arrays, Lists, Stacks & Queues", icon:"🧮", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"11:03", watchSeconds:11, caption:"Visual overview — Core Structures: Arrays, Lists, Stacks & Queues", content:"Arrays store elements in contiguous memory and allow very fast access by index, but inserting or removing an element in the middle can be slow because everything after it must shift. Linked lists trade fast indexed access for fast insertion and removal anywhere in the list, since each element simply points to the next.\n\nStacks follow last-in-first-out order, useful for tasks like undo functionality or tracking function calls, while queues follow first-in-first-out order, useful for tasks like processing jobs in the order they arrive.\n\nRecognising which of these behaviours a problem actually needs is usually more important than memorising the exact implementation details." },
    { id:"m3", title:"Trees, Graphs & Hashing", icon:"🗂️", gradFrom:"#F4A400", gradTo:"#78350F", duration:"11:56", watchSeconds:6, caption:"Visual overview — Trees, Graphs & Hashing", content:"Trees organise data hierarchically, with a root node and child nodes branching downward; binary search trees keep smaller values to the left and larger values to the right, enabling fast searching, insertion and deletion when kept reasonably balanced. Graphs generalise this further, representing arbitrary networks of connections — social networks, maps, dependency chains — using nodes and edges.\n\nHash tables map keys to values using a hash function, achieving average constant-time lookups, insertions and deletions, which makes them one of the most broadly useful structures in practical programming.\n\nUnderstanding how these structures are traversed — depth-first versus breadth-first for trees and graphs — underlies a huge share of classic interview and real-world problems." },
    { id:"m4", title:"Algorithmic Problem Solving", icon:"🎬", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"12:49", watchSeconds:7, caption:"Visual overview — Algorithmic Problem Solving", content:"Sorting and searching are foundational algorithm families: efficient sorting algorithms like merge sort and quicksort run in roughly linearithmic time, far better than naive quadratic approaches, and binary search finds an item in a sorted list in logarithmic time by repeatedly halving the search space.\n\nCommon problem-solving strategies include divide and conquer (breaking a problem into smaller subproblems), dynamic programming (avoiding repeated work by remembering previously computed results), and greedy algorithms (making the locally best choice at each step).\n\nThe most reliable way to improve at algorithms is deliberate, repeated practice: work through a problem by hand first, identify which structure or strategy fits, then implement and test it." },
  ],
  [ // 12 Graphic Design with Photoshop
    { id:"m1", title:"Photoshop Interface & File Basics", icon:"🧬", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"10:47", watchSeconds:11, caption:"Visual overview — Photoshop Interface & File Basics", content:"Photoshop is an image editing tool built around layers — separate, stackable pieces of an image that can be edited, hidden or reordered independently without affecting the rest of the composition. Understanding layers, and organising them with clear names and folders, is the single most important habit for keeping a design project manageable.\n\nUnderstanding the difference between raster images (made of pixels, which lose quality when scaled up) and vector graphics (made of mathematical paths, which scale without quality loss) affects which tool and file type is appropriate for a given task.\n\nSetting the correct canvas size and resolution at the start of a project — matching your intended output, whether screen or print — avoids painful rework later." },
    { id:"m2", title:"Selections, Masking & Retouching", icon:"🪄", gradFrom:"#F4A400", gradTo:"#78350F", duration:"11:40", watchSeconds:6, caption:"Visual overview — Selections, Masking & Retouching", content:"Selection tools let you isolate part of an image to edit without affecting the rest — essential for tasks like changing the colour of a specific object or removing a background. Layer masks take this further by non-destructively hiding parts of a layer, meaning the hidden pixels are not deleted and can be revealed again later.\n\nRetouching tools such as the healing brush and clone stamp let you remove blemishes or unwanted objects by sampling and blending nearby pixels, a technique used constantly in both photography and design work.\n\nWorking non-destructively — using masks and adjustment layers rather than directly altering original pixels — keeps every edit reversible, which is invaluable when a client or your own judgement changes later." },
    { id:"m3", title:"Typography & Composition", icon:"📚", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"12:33", watchSeconds:7, caption:"Visual overview — Typography & Composition", content:"Typography in design work is about more than picking a nice font: consistent sizing, spacing (tracking and leading) and a clear hierarchy between headings and body text determine whether a design is easy or hard to read.\n\nComposition principles like the rule of thirds, alignment and balance guide the eye through a design intentionally rather than leaving it to chance. Consistent alignment between elements — even when they look \"free form\" — is one of the fastest ways to make an amateur design look professional.\n\nGood designers develop the habit of stepping back from their work periodically to judge the overall composition, not just the detail they are currently focused on." },
    { id:"m4", title:"Exporting for Real-World Use", icon:"🧾", gradFrom:"#0891B2", gradTo:"#164E63", duration:"13:26", watchSeconds:8, caption:"Visual overview — Exporting for Real-World Use", content:"Different outputs need different export settings: web images are usually exported as compressed JPEG or PNG files optimised for small file size, while print work requires higher resolution files, often in CMYK colour mode rather than the RGB used for screens.\n\nPhotoshop's export and \"Save for Web\" workflows let you preview file size and quality trade-offs before finalising an export, which matters for website performance.\n\nKeeping an organised, well-labelled source file (with all layers intact) separate from your final exported assets means you can always go back and make changes later without starting over." },
  ],
  [ // 13 Android App Development
    { id:"m1", title:"Kotlin & Android Project Structure", icon:"💡", gradFrom:"#F4A400", gradTo:"#78350F", duration:"11:24", watchSeconds:6, caption:"Visual overview — Kotlin & Android Project Structure", content:"Kotlin is the modern, officially recommended language for Android development, designed to be more concise and safer than Java while remaining fully compatible with existing Android code. An Android project is organised around activities and, increasingly, composable functions if using Jetpack Compose, along with resource files for layouts, strings and images kept separate from code.\n\nUnderstanding the Android app lifecycle — the stages an app or screen goes through, such as being created, paused, resumed or destroyed — is essential, since the operating system can pause or kill your app at almost any time to save resources.\n\nThe manifest file declares what your app needs, including permissions and which screens exist, and is one of the first things worth understanding when opening any new Android project." },
    { id:"m2", title:"Building UI in Android", icon:"🔍", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"12:17", watchSeconds:7, caption:"Visual overview — Building UI in Android", content:"Jetpack Compose lets you build Android UI declaratively — describing what the UI should look like for a given state, similar in spirit to React on the web — rather than manually creating and updating individual UI elements. Composable functions can be combined to build up complex screens from small, reusable pieces.\n\nHandling different screen sizes and orientations gracefully is a bigger concern on Android than on many platforms, given the huge variety of physical devices in use.\n\nState in Compose flows in one direction: data is held higher up and passed down, while events (like a button click) are passed back up as callbacks — a pattern that keeps UI code predictable as it grows." },
    { id:"m3", title:"Data, Networking & Storage", icon:"🧩", gradFrom:"#0891B2", gradTo:"#164E63", duration:"13:10", watchSeconds:8, caption:"Visual overview — Data, Networking & Storage", content:"Android apps typically call a remote API using a networking library such as Retrofit, parse the JSON response, and store some of that data locally using Room (a database library built on SQLite) so the app still works, at least partially, without an internet connection.\n\nCoroutines are Kotlin's tool for writing asynchronous code that reads almost like ordinary sequential code, which makes tasks like network calls far easier to reason about than older callback-based approaches.\n\nRespecting user data and battery: doing network and database work off the main UI thread keeps the app responsive and prevents the dreaded \"app not responding\" error." },
    { id:"m4", title:"Testing, Permissions & Publishing", icon:"🛠️", gradFrom:"#BE185D", gradTo:"#500724", duration:"4:03", watchSeconds:9, caption:"Visual overview — Testing, Permissions & Publishing", content:"Android requires apps to explicitly request sensitive permissions (like camera or location access) at runtime, and to handle the case where a user denies that permission gracefully rather than crashing.\n\nTesting on a range of real or emulated devices, screen sizes and Android versions catches compatibility problems that are easy to miss when only testing on your own phone.\n\nPublishing to the Google Play Store involves preparing a signed release build, store listing assets, and complying with Play Store policies — after which updates can be rolled out gradually to catch problems before they reach every user." },
  ],
  [ // 14 Docker & Kubernetes Essentials
    { id:"m1", title:"Why Containers Exist", icon:"🚀", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"12:01", watchSeconds:7, caption:"Visual overview — Why Containers Exist", content:"A container packages an application together with everything it needs to run — code, runtime, libraries, configuration — so that it behaves the same way regardless of where it is deployed, solving the classic \"it works on my machine\" problem. Unlike a full virtual machine, containers share the host operating system's kernel, making them much lighter and faster to start.\n\nDocker is the most widely used tool for building and running containers. A Dockerfile is a script describing how to build an image — a snapshot of an application and its environment — which can then be run as one or many containers.\n\nImages are built in layers, and Docker caches unchanged layers between builds, which is why the order of instructions in a Dockerfile affects how fast rebuilds are." },
    { id:"m2", title:"Working with Docker", icon:"📐", gradFrom:"#0891B2", gradTo:"#164E63", duration:"12:54", watchSeconds:8, caption:"Visual overview — Working with Docker", content:"Common Docker commands let you build an image from a Dockerfile, run a container from that image, list running containers, and view their logs — a small set of commands covers the vast majority of daily container work.\n\nVolumes let containers persist data beyond their own lifecycle by mapping a folder inside the container to a folder on the host machine or a managed storage location, which matters because containers themselves are usually treated as disposable.\n\nDocker Compose lets you define and run multiple related containers together (for example, an app server and a database) using a single configuration file, which is much simpler than starting each one manually." },
    { id:"m3", title:"Introduction to Kubernetes", icon:"🧠", gradFrom:"#BE185D", gradTo:"#500724", duration:"13:47", watchSeconds:9, caption:"Visual overview — Introduction to Kubernetes", content:"Kubernetes is a system for running many containers reliably across a cluster of machines, automatically restarting failed containers, distributing load, and scaling the number of running copies up or down based on demand. Where Docker runs containers on a single machine, Kubernetes coordinates them across many.\n\nA Pod is the smallest deployable unit in Kubernetes, usually wrapping one container along with shared resources. Deployments describe how many copies of a Pod should be running and how updates should be rolled out, while Services provide a stable network address so other parts of the system can reliably reach a set of Pods even as individual ones are replaced.\n\nKubernetes's declarative model means you describe the desired end state, and Kubernetes continuously works to keep the real cluster matching that description." },
    { id:"m4", title:"Scaling & Operating in Production", icon:"🔗", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:40", watchSeconds:10, caption:"Visual overview — Scaling & Operating in Production", content:"Kubernetes can automatically scale the number of running Pods based on metrics like CPU usage, helping an application handle traffic spikes without manual intervention and scale back down to save cost when demand drops.\n\nHealth checks — probes that ask \"is this container still working correctly?\" — let Kubernetes detect and replace unhealthy containers automatically, improving overall reliability without requiring a human to notice and react.\n\nRunning containers well in production also means centralising logs and metrics from every container into one place, since debugging a problem across dozens of short-lived containers is impractical without proper observability tools." },
  ],
  [ // 15 MongoDB for Beginners
    { id:"m1", title:"Documents Instead of Tables", icon:"📊", gradFrom:"#0891B2", gradTo:"#164E63", duration:"12:38", watchSeconds:8, caption:"Visual overview — Documents Instead of Tables", content:"MongoDB is a NoSQL database that stores data as documents — JSON-like structures that can nest objects and arrays directly — instead of rows in rigid tables. This makes it a natural fit when your data's shape varies between records or maps closely to objects already used in application code.\n\nDocuments are grouped into collections, roughly analogous to tables in a relational database, but without requiring every document in a collection to share exactly the same fields.\n\nThis flexibility is powerful but also a responsibility: without a rigid schema enforced by the database, your application code needs to be more careful and consistent about the shape of the data it writes." },
    { id:"m2", title:"CRUD Operations", icon:"🎯", gradFrom:"#BE185D", gradTo:"#500724", duration:"13:31", watchSeconds:9, caption:"Visual overview — CRUD Operations", content:"The four fundamental database operations — Create, Read, Update and Delete (CRUD) — map to MongoDB methods like insertOne, find, updateOne and deleteOne. Queries are written as JSON-like objects describing which documents to match, which tends to feel intuitive to anyone already comfortable with JavaScript objects.\n\nMongoDB's query language supports rich filtering, including matching nested fields inside documents and arrays, without needing to join separate tables the way a relational database would.\n\nUnderstanding how to structure a query precisely — including which fields to project (return) rather than fetching an entire large document — matters for both correctness and performance." },
    { id:"m3", title:"Schema Design in MongoDB", icon:"🧭", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:24", watchSeconds:10, caption:"Visual overview — Schema Design in MongoDB", content:"Unlike relational databases, where normalization is usually the default, MongoDB often favours embedding related data directly inside a single document when that data is always accessed together — for example, embedding a course's modules inside the course document itself.\n\nReferencing (storing an ID and looking the related document up separately, similar to a foreign key) is preferred when related data is large, changes independently, or is shared across many parent documents.\n\nThere is no single \"correct\" schema in MongoDB — the right design depends on how your application actually reads and writes the data, which is why understanding your access patterns matters more here than in relational design." },
    { id:"m4", title:"Indexing & Aggregation", icon:"📌", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:17", watchSeconds:11, caption:"Visual overview — Indexing & Aggregation", content:"Just like relational databases, MongoDB uses indexes to speed up queries on frequently searched fields; without an appropriate index, a query must scan every document in a collection.\n\nThe aggregation pipeline lets you process documents through a sequence of stages — filtering, grouping, reshaping — to produce summarised or transformed results, similar in spirit to SQL's GROUP BY but considerably more flexible.\n\nAs with any database, understanding how your specific queries actually run (using explain plans) is the most reliable way to improve performance rather than guessing at optimisations." },
  ],
  [ // 16 Digital Marketing Basics
    { id:"m1", title:"The Digital Marketing Landscape", icon:"🖼️", gradFrom:"#BE185D", gradTo:"#500724", duration:"13:15", watchSeconds:9, caption:"Visual overview — The Digital Marketing Landscape", content:"Digital marketing covers every channel used to reach an audience online: search engines, social media, email, and paid advertising. Each channel suits different goals — search is strong for capturing existing intent, while social media is stronger for building awareness among people not yet actively searching.\n\nA useful first step for any campaign is defining a clear, specific goal (more sign-ups, more sales, more awareness) and a target audience, since the right channel and message depend heavily on both.\n\nDigital marketing's biggest advantage over traditional marketing is measurability — nearly every action can be tracked, letting you learn what works and adjust quickly rather than waiting until a campaign ends." },
    { id:"m2", title:"SEO Fundamentals", icon:"🧱", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:08", watchSeconds:10, caption:"Visual overview — SEO Fundamentals", content:"Search Engine Optimisation (SEO) is the practice of improving a website so it ranks higher in search results for relevant queries, driving free (\"organic\") traffic. It rests on three broad pillars: technical SEO (making sure a site is fast and crawlable by search engines), on-page SEO (relevant, well-structured content targeting the right keywords), and off-page SEO (other reputable sites linking back to yours).\n\nKeyword research — understanding what real people actually search for — should guide content creation, rather than writing content first and hoping it happens to match what people search.\n\nSEO is a long-term strategy: meaningful ranking improvements typically take weeks or months, not days, which is an important expectation to set from the start." },
    { id:"m3", title:"Social Media & Content Marketing", icon:"⚙️", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:01", watchSeconds:11, caption:"Visual overview — Social Media & Content Marketing", content:"Different social platforms have different audiences and content styles, so an effective strategy adapts format and tone per platform rather than posting the exact same content everywhere. Content marketing — creating genuinely useful articles, videos or guides — builds trust and audience over time rather than directly selling in every piece of content.\n\nConsistency matters more than perfection: a realistic, sustainable posting schedule that you can maintain long-term outperforms an intense short burst of activity that quickly fizzles out.\n\nEngaging with comments and messages, not just publishing content, is part of what builds an actual community around a brand rather than a one-way broadcast." },
    { id:"m4", title:"Paid Advertising & Analytics", icon:"🔬", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:54", watchSeconds:6, caption:"Visual overview — Paid Advertising & Analytics", content:"Paid advertising (such as search ads or social media ads) lets you pay to reach a specific, targeted audience immediately, which is useful for testing messaging quickly or driving traffic before organic efforts have had time to grow.\n\nKey metrics to track include click-through rate (how many people who saw an ad clicked it), conversion rate (how many of those completed the desired action), and cost per acquisition (how much you spent per successful outcome) — together these show whether a campaign is actually working, not just generating clicks.\n\nAnalytics tools let you tie all channels together into one picture, showing which combination of channels actually drives real results so budget can be shifted toward what works." },
  ],
  [ // 17 Java Programming Masterclass
    { id:"m1", title:"Java Syntax & the JVM", icon:"📡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"13:52", watchSeconds:10, caption:"Visual overview — Java Syntax & the JVM", content:"Java code is compiled into bytecode that runs on the Java Virtual Machine (JVM), which is what allows the same compiled Java program to run unmodified on Windows, macOS or Linux — the well-known \"write once, run anywhere\" idea.\n\nJava is statically typed, meaning variable types are checked at compile time rather than at runtime, which catches a category of bugs early compared to dynamically typed languages, at the cost of a bit more upfront verbosity.\n\nUnderstanding the basic building blocks — variables, control flow (if/else, loops), and methods — is the foundation everything else in Java is built on." },
    { id:"m2", title:"Object-Oriented Programming in Java", icon:"🧮", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"4:45", watchSeconds:11, caption:"Visual overview — Object-Oriented Programming in Java", content:"Java is built around object-oriented programming: classes define the blueprint for objects, bundling together data (fields) and behaviour (methods) that belong together conceptually. Encapsulation — keeping an object's internal data private and exposing controlled access through methods — protects an object from being put into an invalid state by outside code.\n\nInheritance lets a class reuse and extend behaviour from another class, while interfaces define a contract of methods a class promises to implement, without dictating how. Polymorphism allows code to work with objects of different concrete types through a shared interface or parent class, without needing to know the exact type at compile time.\n\nGood object-oriented design favours composition (building complex objects out of simpler ones) alongside inheritance, rather than relying on inheritance for everything." },
    { id:"m3", title:"Collections & Exception Handling", icon:"🗂️", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:38", watchSeconds:6, caption:"Visual overview — Collections & Exception Handling", content:"The Java Collections Framework provides ready-made, well-tested data structures like ArrayList, HashMap and HashSet, saving you from reimplementing common structures from scratch and providing consistent, efficient behaviour.\n\nException handling with try/catch lets a program respond gracefully to unexpected situations (like a missing file or invalid input) instead of crashing outright. Java distinguishes checked exceptions, which the compiler forces you to handle or declare, from unchecked exceptions, which represent programming errors that typically should not be silently swallowed.\n\nWriting clear, specific exception handling — rather than catching every possible error the same generic way — makes bugs far easier to diagnose later." },
    { id:"m4", title:"Building Larger Java Applications", icon:"🎬", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:31", watchSeconds:7, caption:"Visual overview — Building Larger Java Applications", content:"As a Java project grows, organising code into packages (namespaces that group related classes) keeps a large codebase navigable, and build tools like Maven or Gradle manage dependencies and automate compiling, testing and packaging.\n\nUnit testing with a framework like JUnit lets you verify that individual pieces of code behave correctly, and catch regressions automatically whenever code changes, rather than relying only on manual testing.\n\nModern Java development typically follows a layered structure — separating data access, business logic and presentation — which mirrors object-oriented principles applied at the scale of an entire application rather than a single class." },
  ],
  [ // 18 Deep Learning with TensorFlow
    { id:"m1", title:"Neural Networks from First Principles", icon:"🧬", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"4:29", watchSeconds:11, caption:"Visual overview — Neural Networks from First Principles", content:"A neural network is built from layers of simple units (\"neurons\") that each combine their inputs with learned weights and pass the result through a non-linear activation function. Stacking many such layers lets a network learn increasingly abstract representations of its input, which is where the \"deep\" in deep learning comes from.\n\nTraining a network means adjusting its weights so that its predictions get closer to the correct answers, measured by a loss function that quantifies how wrong a prediction currently is.\n\nBackpropagation, combined with an optimisation algorithm like gradient descent, is the mechanism that efficiently calculates how to adjust every weight in the network to reduce that loss." },
    { id:"m2", title:"Building Models with TensorFlow & Keras", icon:"🪄", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:22", watchSeconds:6, caption:"Visual overview — Building Models with TensorFlow & Keras", content:"TensorFlow is a library for building and training machine learning models efficiently, including on specialised hardware like GPUs, and Keras (built into TensorFlow) provides a much friendlier, high-level API for defining a network layer by layer.\n\nA typical Keras workflow involves defining a model's architecture, compiling it with a chosen optimiser and loss function, and calling fit with your training data, which handles the actual training loop for you.\n\nMonitoring training and validation loss during training is essential — a widening gap between the two is the classic sign of overfitting, where a model is memorising rather than generalising." },
    { id:"m3", title:"Convolutional & Sequential Architectures", icon:"📚", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:15", watchSeconds:7, caption:"Visual overview — Convolutional & Sequential Architectures", content:"Convolutional Neural Networks (CNNs) are specialised for image data: convolutional layers scan small patches of an image with learned filters that detect features like edges or textures, and stacking these layers lets the network build up from simple features to complex ones like shapes or objects.\n\nRecurrent architectures and their modern successors (like Transformers) are specialised for sequential data such as text or time series, where the order of inputs carries important meaning that simple feed-forward networks would ignore.\n\nChoosing an architecture family that matches the structure of your data is usually more impactful on final performance than fine-tuning every other detail of a poorly matched architecture." },
    { id:"m4", title:"Training Well & Avoiding Common Pitfalls", icon:"🧾", gradFrom:"#F4A400", gradTo:"#78350F", duration:"7:08", watchSeconds:8, caption:"Visual overview — Training Well & Avoiding Common Pitfalls", content:"Techniques like dropout (randomly disabling some neurons during training) and data augmentation (creating varied versions of training examples) help a network generalise better rather than simply memorising the training set.\n\nTransfer learning — starting from a large model already trained on a huge dataset and fine-tuning it for your specific task — often produces excellent results with far less data and computation than training a network entirely from scratch.\n\nDeep learning models can be powerful but opaque; understanding at least roughly why a model makes a given prediction, using interpretability techniques, is increasingly considered a responsibility rather than an optional extra." },
  ],
  [ // 19 Figma UI Design Bootcamp
    { id:"m1", title:"Figma Fundamentals", icon:"💡", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"5:06", watchSeconds:6, caption:"Visual overview — Figma Fundamentals", content:"Figma is a browser-based design tool built around frames (containers representing screens or sections) and layers within them, with the major advantage of being fully collaborative in real time, similar to editing a shared document.\n\nComponents in Figma let you define a reusable element once — a button, a card — and reuse it throughout a design; updating the original component automatically updates every place it is used, which keeps large design files consistent.\n\nOrganising a file with clear naming, consistent frame sizes and sensible page structure pays off enormously as a project grows, both for yourself and for anyone else who opens the file later." },
    { id:"m2", title:"Auto Layout & Responsive Components", icon:"🔍", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"5:59", watchSeconds:7, caption:"Visual overview — Auto Layout & Responsive Components", content:"Auto Layout is Figma's answer to responsive, flexible design directly inside the design tool — similar in spirit to Flexbox on the web — automatically handling spacing and resizing as content inside a frame changes.\n\nUsing Auto Layout well means designs can be resized or have content added without every element needing to be manually repositioned, closely mirroring how a real, responsive interface will behave once built.\n\nCombining Auto Layout with components lets you build a small design system — consistent buttons, inputs and cards — that keeps an entire product feeling cohesive." },
    { id:"m3", title:"Prototyping Interactions", icon:"🧩", gradFrom:"#F4A400", gradTo:"#78350F", duration:"6:52", watchSeconds:8, caption:"Visual overview — Prototyping Interactions", content:"Figma's prototyping mode lets you link frames together with interactions — for example, a button click navigating to another screen — turning a set of static designs into a clickable, testable flow.\n\nAdding realistic transitions and states (like a button's hover or pressed appearance) helps stakeholders and test users experience something much closer to the final product than static screens alone.\n\nSharing a prototype link allows others to test the flow directly in their browser without needing Figma installed, which is invaluable for gathering feedback quickly." },
    { id:"m4", title:"Design Systems & Developer Handoff", icon:"🛠️", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:45", watchSeconds:9, caption:"Visual overview — Design Systems & Developer Handoff", content:"A design system is a shared library of reusable components, colours, typography styles and spacing rules that keeps a product's interface consistent as more people work on it and as it grows over time.\n\nFigma's inspect panel lets developers see exact spacing, colours, and export assets directly from a design file, substantially reducing ambiguity during handoff compared to relying only on verbal or written specifications.\n\nMaintaining a design system requires ongoing discipline: as new patterns emerge, they should be added back into the shared library rather than left as one-off exceptions scattered through individual files." },
  ],
  [ // 20 Cybersecurity Fundamentals
    { id:"m1", title:"Thinking Like a Defender", icon:"🚀", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"5:43", watchSeconds:7, caption:"Visual overview — Thinking Like a Defender", content:"Cybersecurity is fundamentally about managing risk: understanding what needs protecting, what could go wrong, and how likely and costly each scenario would be, rather than trying to prevent every conceivable attack equally.\n\nThe CIA triad — Confidentiality (keeping data private), Integrity (keeping data accurate and unaltered) and Availability (keeping systems accessible when needed) — is a foundational way to reason about what security is actually trying to protect.\n\nMost real-world breaches exploit simple, well-known weaknesses — weak passwords, unpatched software, careless configuration — far more often than exotic, novel attack techniques." },
    { id:"m2", title:"Common Threats & Attack Techniques", icon:"📐", gradFrom:"#F4A400", gradTo:"#78350F", duration:"6:36", watchSeconds:8, caption:"Visual overview — Common Threats & Attack Techniques", content:"Phishing — tricking someone into revealing credentials or clicking a malicious link, usually via a convincing fake email or message — remains one of the most common ways attackers gain initial access, because it targets people rather than technical systems directly.\n\nMalware (malicious software) includes viruses, ransomware and spyware, each designed to damage, extort or spy on a system once it gains a foothold. Social engineering broadly refers to manipulating people rather than exploiting purely technical flaws, and often succeeds specifically because it bypasses technical defences entirely.\n\nUnderstanding attacker motivations and common techniques helps prioritise defences toward the risks that are actually most likely to be exploited." },
    { id:"m3", title:"Core Defensive Practices", icon:"🧠", gradFrom:"#D93025", gradTo:"#7F1D1D", duration:"7:29", watchSeconds:9, caption:"Visual overview — Core Defensive Practices", content:"Strong, unique passwords combined with multi-factor authentication (requiring a second proof of identity beyond a password) dramatically reduce the risk of account compromise, even if a password is somehow leaked or guessed.\n\nKeeping software updated matters because many attacks exploit publicly known vulnerabilities in outdated software — patching promptly closes doors that are otherwise left wide open. Encryption protects data both at rest (stored on disk) and in transit (moving across a network), so that even intercepted data remains unreadable without the correct key.\n\nThe principle of least privilege — giving users and systems only the access they genuinely need — limits the potential damage if any single account or system is compromised." },
    { id:"m4", title:"Incident Response & Security Culture", icon:"🔗", gradFrom:"#0891B2", gradTo:"#164E63", duration:"8:22", watchSeconds:10, caption:"Visual overview — Incident Response & Security Culture", content:"No defence is perfect, so having a clear incident response plan — what to do the moment a breach is suspected, who to notify, and how to contain the damage — significantly reduces the impact when something does go wrong.\n\nRegular backups, tested to confirm they can actually be restored, are one of the most effective defences against ransomware specifically, since they remove the attacker's main point of leverage.\n\nSecurity is ultimately a shared responsibility across an entire organisation, not solely a technical team's job; ongoing awareness training helps everyone recognise and resist common attacks like phishing." },
  ],
  [ // 21 DevOps & CI/CD Pipelines
    { id:"m1", title:"Why DevOps Exists", icon:"💡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:40", watchSeconds:7, caption:"Visual overview — Why DevOps Exists", content:"DevOps is the practice of breaking down the traditional wall between developers (who write code) and operations (who run it in production), so that both groups share responsibility for shipping software quickly and reliably. It's as much a cultural shift as a technical one.\n\nBefore DevOps, code could sit finished for weeks waiting for a separate team to deploy it, and failures in production were often blamed on \"the other team.\" DevOps replaces that hand-off with shared ownership, automation and fast feedback loops.\n\nThe payoff is measurable: teams that practise DevOps well tend to deploy far more often, with far fewer failures, because small frequent changes are easier to reason about than big risky ones." },
    { id:"m2", title:"Version Control & Branching Strategy", icon:"🔍", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:35", watchSeconds:8, caption:"Visual overview — Version Control & Branching Strategy", content:"Git underpins almost every modern DevOps workflow: every change lives in a commit, and branches let multiple people work in parallel without stepping on each other's code. A clear branching strategy (such as trunk-based development or feature branches merged via pull requests) keeps a growing team's changes organised and reviewable.\n\nCode review, enforced through pull requests, is where a second set of eyes catches bugs, security issues and design problems before they reach production — treat it as a core safety mechanism, not a formality.\n\nA repository's history is also documentation: clear, honest commit messages make it far easier to understand why a change was made months later." },
    { id:"m3", title:"Building CI Pipelines", icon:"🧩", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"6:20", watchSeconds:9, caption:"Visual overview — Building CI Pipelines", content:"Continuous Integration (CI) means automatically building and testing every change the moment it's pushed, so problems are caught in minutes rather than being discovered days later by someone else. A CI pipeline typically installs dependencies, runs automated tests, and reports a clear pass/fail result on every commit.\n\nTools like GitHub Actions, GitLab CI and Jenkins let you define these pipelines as configuration files that live alongside your code, so the pipeline itself is versioned and reviewable just like application code.\n\nA red (failing) pipeline should block a change from merging — the entire value of CI comes from treating that signal as non-negotiable rather than optional." },
    { id:"m4", title:"Continuous Deployment & Monitoring", icon:"🏆", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"7:05", watchSeconds:10, caption:"Visual overview — Continuous Deployment & Monitoring", content:"Continuous Deployment extends CI one step further: once a change passes all automated checks, it's deployed to production automatically, without a manual release step. This only works safely alongside strong automated tests and the ability to detect and roll back problems fast.\n\nDeployment strategies such as blue-green deployments or canary releases reduce risk further by exposing a new version to a small slice of real traffic before rolling it out fully.\n\nNone of this matters without monitoring: dashboards, logs and alerts that tell you immediately when something is wrong in production, closing the loop between shipping code and knowing its real-world impact." },
  ],
  [ // 22 Generative AI & Prompt Engineering
    { id:"m1", title:"How Large Language Models Work", icon:"💡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:25", watchSeconds:7, caption:"Visual overview — How Large Language Models Work", content:"A large language model (LLM) is trained on huge amounts of text to predict, one piece at a time, what word is likely to come next given everything before it. From this simple objective, applied at enormous scale, surprisingly general abilities emerge — answering questions, writing code, summarising and reasoning through problems.\n\nIt helps to think of an LLM as a very well-read pattern-completion engine rather than a database of facts: it generates plausible continuations of your text, which is usually accurate but is not guaranteed to be, especially on obscure or rapidly changing information.\n\nUnderstanding this generative, probabilistic nature is the foundation for using these models well and knowing when to double-check their output." },
    { id:"m2", title:"Anatomy of a Good Prompt", icon:"🔍", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:15", watchSeconds:8, caption:"Visual overview — Anatomy of a Good Prompt", content:"A prompt is the instruction you give a model, and small changes to it can noticeably change the quality of the result. Effective prompts are usually specific about the task, the desired format, and any constraints, rather than vague and open-ended.\n\nProviding examples of the input/output pattern you want (sometimes called few-shot prompting) is one of the most reliable ways to steer a model toward a consistent style or structure without writing lengthy instructions.\n\nAsking a model to reason step by step before giving a final answer often improves accuracy on harder problems, because it gives the model room to work through the problem rather than jumping straight to a guess." },
    { id:"m3", title:"Practical Prompting Techniques", icon:"🧩", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"6:10", watchSeconds:9, caption:"Visual overview — Practical Prompting Techniques", content:"Splitting a complex task into smaller prompts — first outline, then draft, then refine — usually produces better results than asking for the entire finished output in one shot, since each step is easier for the model to get right.\n\nGiving a model a role or persona (\"you are an experienced editor\") and clear context about the audience or purpose often shapes tone and depth more effectively than repeating instructions.\n\nTreat your first prompt as a draft: iterating based on what the model actually returns, rather than expecting a perfect result immediately, is standard practice even for experienced prompt engineers." },
    { id:"m4", title:"Limitations, Safety & Responsible Use", icon:"🏆", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:55", watchSeconds:10, caption:"Visual overview — Limitations, Safety & Responsible Use", content:"Models can produce confident-sounding but incorrect statements, a failure mode often called hallucination. For anything factual, high-stakes or easily verifiable, always cross-check important claims rather than trusting fluent-sounding output at face value.\n\nModels can also reflect biases present in their training data, and can be misused to generate misleading or harmful content, which is why responsible platforms apply safety guidelines and content policies around how these tools can be used.\n\nUsed well — with clear prompts, healthy scepticism about factual claims, and an understanding of its limits — generative AI is a genuinely powerful assistant for writing, coding, research and brainstorming." },
  ],
  [ // 23 Swift & iOS App Development
    { id:"m1", title:"Swift Language Basics", icon:"💡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:50", watchSeconds:7, caption:"Visual overview — Swift Language Basics", content:"Swift is Apple's modern programming language for iOS, iPadOS and macOS development, designed to be safe, expressive and fast. Its type system catches many common bugs at compile time, before your app ever runs, by requiring you to be explicit about the kind of data a variable holds.\n\nOptionals are one of Swift's defining features: a value is either present or explicitly marked as possibly absent, forcing you to handle the \"missing value\" case deliberately rather than crashing unexpectedly at runtime.\n\nGetting comfortable with Swift's syntax — structs, functions, closures and optionals — is the foundation everything else in iOS development is built on." },
    { id:"m2", title:"SwiftUI & Building Interfaces", icon:"🔍", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:40", watchSeconds:8, caption:"Visual overview — SwiftUI & Building Interfaces", content:"SwiftUI lets you build iOS interfaces declaratively — describing what a screen should look like for a given piece of state — similar in spirit to how React works on the web, rather than manually managing individual UI elements.\n\nViews in SwiftUI are small, composable structs that can be combined to build up entire screens, and SwiftUI automatically updates the interface whenever the underlying state changes, without you writing manual refresh logic.\n\nApple's live preview lets you see UI changes almost instantly as you write code, which makes iterating on layout and design dramatically faster than the older build-and-run cycle." },
    { id:"m3", title:"App Architecture & Navigation", icon:"🧩", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"6:25", watchSeconds:9, caption:"Visual overview — App Architecture & Navigation", content:"As an app grows beyond a single screen, organising navigation and state becomes essential. Common patterns like MVVM (Model-View-ViewModel) separate what a screen displays from the logic that prepares and manages its data, keeping views simple and logic testable.\n\niOS navigation typically involves stacks of screens pushed and popped as a user moves through the app, plus modal sheets for temporary, focused tasks — understanding when to use each keeps an app's flow intuitive.\n\nSharing state across multiple screens, such as a logged-in user's profile, is usually handled through observable objects that views automatically react to whenever the underlying data changes." },
    { id:"m4", title:"Testing, Polish & App Store Submission", icon:"🏆", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"7:10", watchSeconds:10, caption:"Visual overview — Testing, Polish & App Store Submission", content:"Before shipping, an app should be tested on multiple device sizes and iOS versions, since layout and behaviour can subtly differ across Apple's hardware lineup. Automated unit and UI tests catch regressions early, especially as more people contribute to a growing codebase.\n\nPolish matters more on iOS than many platforms: consistent spacing, native-feeling animations, and respecting system conventions (like dark mode and accessibility settings) are what separate an app that feels \"finished\" from one that merely works.\n\nSubmitting to the App Store involves configuring app metadata, screenshots and privacy details, then passing Apple's review process — budgeting time for review and potential rejections is an important part of any real launch plan." },
  ],
  [ // 24 Vue.js Frontend Development
    { id:"m1", title:"Vue Fundamentals & Reactivity", icon:"💡", gradFrom:"#0A66C2", gradTo:"#0D2B4E", duration:"4:35", watchSeconds:7, caption:"Visual overview — Vue Fundamentals & Reactivity", content:"Vue.js is a progressive front-end framework built around a simple idea: bind your data to your template, and Vue automatically keeps the two in sync as data changes. This is called reactivity, and it removes the need to manually find and update DOM elements yourself.\n\nA Vue component combines a template (HTML-like markup), script (logic and data) and style in one file, which keeps everything related to one piece of UI in a single place rather than scattered across a project.\n\nUnderstanding how Vue tracks changes to your data — and re-renders only the parts of the page that actually depend on that data — helps you write components that stay fast even as an application grows." },
    { id:"m2", title:"Components & Props", icon:"🔍", gradFrom:"#7C3AED", gradTo:"#2E1065", duration:"5:25", watchSeconds:8, caption:"Visual overview — Components & Props", content:"Vue applications are built from components — reusable, self-contained pieces of UI that can be nested inside one another to build complex interfaces from small, well-defined pieces. Props let a parent component pass data down into a child, keeping data flow predictable and easy to trace.\n\nEvents let a child component communicate back up to its parent (for example, notifying it that a button was clicked), completing a clear, one-directional flow of data down and events up.\n\nDesigning components with a single, clear responsibility — rather than components that try to do everything — is what keeps a Vue codebase maintainable as it grows past a handful of screens." },
    { id:"m3", title:"The Composition API", icon:"🧩", gradFrom:"#0F9D58", gradTo:"#064E3B", duration:"6:15", watchSeconds:9, caption:"Visual overview — The Composition API", content:"The Composition API lets you organise a component's logic by feature rather than by option type, using functions like ref and reactive to create pieces of reactive state directly inside your component's setup function.\n\nThis makes it far easier to extract and reuse logic across components through composable functions — small, focused functions that encapsulate a specific piece of stateful behaviour, similar in spirit to React hooks.\n\nFor components with more than a little logic, the Composition API tends to scale better than the older Options API, because related code stays grouped together instead of being split across separate data, methods and computed sections." },
    { id:"m4", title:"Routing, State & Production Builds", icon:"🏆", gradFrom:"#EA580C", gradTo:"#7C2D12", duration:"6:50", watchSeconds:10, caption:"Visual overview — Routing, State & Production Builds", content:"Vue Router maps URLs to components, enabling multi-page-feeling single-page applications where navigating between views doesn't require a full page reload. Nested routes and route parameters let you build complex navigation structures cleanly.\n\nFor state shared across many components — like the currently logged-in user — a dedicated state management library such as Pinia keeps that shared data in one predictable place rather than passing it manually through many layers of components.\n\nWhen you're ready to ship, Vue's build tooling bundles and optimises your application into small, cached, production-ready files — a critical step that keeps real-world load times fast for actual users." },
  ],
];

export const TAG_MAP = {
  'Web Development':'tag-blue','Data Science':'tag-green','Design':'tag-orange',
  'Cloud':'tag-blue','Mobile':'tag-orange','Database':'tag-warn','Other':'tag-purple'
};

export const CATEGORY_THEME = {
  'Web Development': { field:'web development', unit:'application', practice:'building and styling real pages and components', toolset:'HTML, CSS, JavaScript and modern front-end/back-end tooling' },
  'Data Science':    { field:'data science',     unit:'dataset',     practice:'cleaning, analysing and visualising real data',        toolset:'Python and its data analysis libraries' },
  'Design':          { field:'design',           unit:'interface',   practice:'wireframing, prototyping and refining a real interface', toolset:'modern design and prototyping tools' },
  'Cloud':           { field:'cloud computing',  unit:'system',      practice:'provisioning and configuring real cloud infrastructure', toolset:'cloud platform services' },
  'Mobile':          { field:'mobile development', unit:'app',       practice:'building and testing a real mobile app',                toolset:'a modern mobile SDK and framework' },
  'Database':        { field:'database design',  unit:'schema',      practice:'modelling data and writing real queries',               toolset:'a relational or NoSQL database engine' },
  'Other':           { field:'the subject',      unit:'topic',       practice:'applying what you learn to a real, hands-on example',   toolset:'industry-standard tools' },
};


export const MODULE_STYLE = [
  { icon:'💡', gradFrom:'#0A66C2', gradTo:'#0D2B4E', duration:'4:30', watchSeconds:7 },
  { icon:'🧩', gradFrom:'#7C3AED', gradTo:'#2E1065', duration:'5:45', watchSeconds:8 },
  { icon:'🛠️', gradFrom:'#0F9D58', gradTo:'#064E3B', duration:'6:30', watchSeconds:9 },
  { icon:'🏆', gradFrom:'#EA580C', gradTo:'#7C2D12', duration:'7:15', watchSeconds:10 },
];
export function generateModulesForCourse(course) {
  const theme = CATEGORY_THEME[course.category] || CATEGORY_THEME['Other'];
  const desc  = (course.description || '').trim();
  const descLine = desc ? ` This course puts it directly: "${desc}"` : '';
  const levelLower = (course.level || 'Beginner').toLowerCase();
  const levelArticle = /^[aeiou]/.test(levelLower) ? 'an' : 'a';

  const stages = [
    {
      title: `Introduction to ${course.title}`,
      content:
        `Welcome to ${course.title}. This course is ${levelArticle} ${levelLower}-level course in ${theme.field}, taught by ${course.instructor}, and is built around ${theme.practice}.${descLine}\n\n` +
        `Before diving into hands-on work, it helps to understand the shape of the course ahead: over ${course.duration} hours and ${course.lessons} lessons, you will move from foundational ideas to real, applied practice. Each module in this course combines a short visual overview, a recorded lecture, and written theory you can revisit at any time.\n\n` +
        `By the end of this module you should be able to describe, in your own words, what ${theme.field} actually involves and what you will be able to build or do once you finish ${course.title}.`,
    },
    {
      title: `Core Concepts in ${course.category}`,
      content:
        `Every area of ${theme.field} rests on a small set of core ideas that everything else builds on. In this module we slow down and focus on exactly those fundamentals, rather than rushing toward advanced techniques you aren't yet ready to use well.\n\n` +
        `Expect to see the vocabulary and mental models that ${theme.field} professionals use every day — the kind of foundation that makes documentation, tutorials and expert conversations click into place once you have it, rather than sounding like a wall of jargon.\n\n` +
        `Take your time here. Skimming the fundamentals is the single most common reason learners get stuck later in a course like ${course.title}, so treat this module as the foundation the rest of the course is built on.`,
    },
    {
      title: `Practical ${course.category} Techniques`,
      content:
        `Theory only becomes a real skill once you use it, so this module is centred on ${theme.practice} using ${theme.toolset}. You will apply what you learned in the previous module to something concrete, rather than continuing to study ideas in the abstract.\n\n` +
        `Working ${levelLower}-level learners through practical exercises like this is exactly how ${course.instructor} designed this course — small, achievable tasks that compound into real capability, each one slightly harder than the last.\n\n` +
        `If something doesn't work the first time, that's a normal and useful part of the process: debugging your own mistakes is often where the deepest learning in ${theme.field} actually happens.`,
    },
    {
      title: `Advanced ${course.title} Mastery`,
      content:
        `In this final module we bring everything together. You'll revisit the foundations from earlier modules and combine them with the practical techniques you've just practised, working toward the kind of finished result that reflects real competence in ${theme.field}.\n\n` +
        `This is also a good point to reflect on how far you've come: at the start of ${course.title} these ideas were unfamiliar, and by now you should be able to reason about them confidently and explain them to someone else — a strong sign that the learning has actually stuck.\n\n` +
        `Once you complete this module, your course progress will reach 100% and your certificate for ${course.title} will unlock automatically — a record of real, verifiable work in ${theme.field}.`,
    },
  ];

  return stages.map((s, i) => ({
    id: 'm' + (i + 1),
    title: s.title,
    icon: MODULE_STYLE[i].icon,
    gradFrom: MODULE_STYLE[i].gradFrom,
    gradTo: MODULE_STYLE[i].gradTo,
    duration: MODULE_STYLE[i].duration,
    watchSeconds: MODULE_STYLE[i].watchSeconds,
    caption: 'Visual overview — ' + s.title,
    content: s.content,
  }));
}
